widget.solution:
def is_connected(X, tau):
    """True if no proper non-empty open set has an open complement."""
    X = frozenset(X)
    opens = set(tau)
    return not any(U and U != X and (X - U) in opens for U in opens)

def components(X, tau):
    """The components, as a sorted list of sorted strings."""
    X = frozenset(X)
    opens = set(tau)
    clopen = [U for U in opens if (X - U) in opens]
    comps = set()
    for x in X:
        c = X
        for U in clopen:
            if x in U:
                c = c & U
        comps.add("".join(sorted(c)))
    return sorted(comps)
